import { MakeLogicType, afterMount, connect, kea, listeners, path } from 'kea'
import { loaders } from 'kea-loaders'

import { productSetupStatusLogic } from 'lib/components/ProductEmptyState/productSetupStatusLogic'
import type { ProductSetupStatus } from 'lib/components/ProductEmptyState/types'
import { teamLogic } from 'scenes/teamLogic'

import { ProductKey } from '~/queries/schema/schema-general'

import { earlyAccessFeatureList } from 'products/early_access_features/frontend/generated/api'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface earlyAccessFeaturesSetupLogicValues {
    setupStatus: ProductSetupStatus // productSetupStatusLogic
    currentProjectId: number | string // teamLogic
    featureCount: number | null
    featureCountLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface earlyAccessFeaturesSetupLogicActions {
    setDetectedStatus: (status: ProductSetupStatus) => {
        status: ProductSetupStatus
    } // productSetupStatusLogic
    loadFeatureCount: (_: void) => void
    loadFeatureCountFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadFeatureCountSuccess: (
        featureCount: number,
        payload?: void
    ) => {
        featureCount: number
        payload?: void
    }
}

export type earlyAccessFeaturesSetupLogicType = MakeLogicType<
    earlyAccessFeaturesSetupLogicValues,
    earlyAccessFeaturesSetupLogicActions
>

/**
 * Setup detection for the early access features empty state. Early access is a
 * creation-first product, so "set up" simply means the project has at least one
 * feature - no event or traffic signal involved. Re-checks on every mount (the
 * scene gate mounts it), which covers returning from the feature creation page.
 */
export const earlyAccessFeaturesSetupLogic = kea<earlyAccessFeaturesSetupLogicType>([
    path(['products', 'early_access_features', 'frontend', 'emptyState', 'earlyAccessFeaturesSetupLogic']),
    connect(() => ({
        actions: [productSetupStatusLogic({ productKey: ProductKey.EARLY_ACCESS_FEATURES }), ['setDetectedStatus']],
        values: [
            productSetupStatusLogic({ productKey: ProductKey.EARLY_ACCESS_FEATURES }),
            ['status as setupStatus'],
            teamLogic,
            ['currentProjectId'],
        ],
    })),
    loaders(({ values }) => ({
        featureCount: [
            null as number | null,
            {
                loadFeatureCount: async (_: void, breakpoint): Promise<number> => {
                    const response = await earlyAccessFeatureList(String(values.currentProjectId), { limit: 1 })
                    breakpoint()
                    return response.count
                },
            },
        ],
    })),
    listeners(({ actions, values }) => ({
        loadFeatureCountSuccess: ({ featureCount }) => {
            actions.setDetectedStatus(featureCount !== null && featureCount > 0 ? 'has-data' : 'needs-setup')
        },
        loadFeatureCountFailure: () => {
            // Never strand the gate on its spinner: if nothing has answered yet, fail
            // open to the real scene. Don't downgrade an existing answer on a blip.
            if (values.setupStatus === 'loading') {
                actions.setDetectedStatus('unknown')
            }
        },
    })),
    afterMount(({ actions }) => {
        actions.loadFeatureCount()
    }),
])
